// A ParamSizeError reports that the library wrote a number of bytes other than
// the size of the storage it was given. It means the caller's Go type and the
// library's idea of the parameter no longer agree, which is a mismatch between
// this package and the installed libcudss, not a caller error.
type ParamSizeError struct {
	Param string
	Want  uintptr
	Got   uintptr
}

// Error reports the parameter and the two sizes.
func (e *ParamSizeError) Error() string {
	return "cudss: " + e.Param + ": library wrote " + itoa(e.Got) + " bytes into " + itoa(e.Want) + " bytes of storage"
}

func itoa(v uintptr) string {
	if v == 0 {
		return "0"
	}
	var buf [20]byte
	i := len(buf)
	for v > 0 {
		i--
		buf[i] = byte('0' + v%10)
		v /= 10
	}
	return string(buf[i:])
}

// configSet writes size bytes from value into the config parameter param.
//
// It is unexported on purpose: size is the caller's claim about value, and the
// library trusts it. Every caller in this package derives size with
// unsafe.Sizeof from the same storage value points at.
func configSet(config Config, param ConfigParam, value unsafe.Pointer, size uintptr) error {
	if err := checkLibSym("cudssConfigSet"); err != nil {
		return err
	}
	return toError(fnConfigSet(config, param, value, uint(size)))
}

// configGet reads the config parameter param into size bytes at value and
// reports how many bytes the library wrote. See configSet on why it is
// unexported.
func configGet(config Config, param ConfigParam, value unsafe.Pointer, size uintptr) (uintptr, error) {
	if err := checkLibSym("cudssConfigGet"); err != nil {
		return 0, err
	}
	var written uint
	if err := toError(fnConfigGet(config, param, value, uint(size), &written)); err != nil {
		return 0, err
	}
	return uintptr(written), nil
}

