// ParamElement is the set of element types a cuDSS array parameter can have.
//
// Which one a given parameter needs is not free: an index-typed parameter
// takes the index type the system matrix was created with, and a value-typed
// parameter takes its value type. Reading a parameter with the wrong element
// type is not caught by the library, so DataArray checks the number of bytes
// written and reports *ParamSizeError when it is not a whole number of
// elements of the requested type.
type ParamElement interface {
	~int32 | ~int64 | ~float32 | ~float64
}

// DataArray reads an array-valued data parameter into dst and reports how many
// elements the library wrote.
//
// dst fixes the byte count handed to the library, so the call cannot write
// past it. dst must be long enough for the whole parameter: cuDSS does not
// report a required length, and a short buffer is an error from the library,
// not a partial read. T must match the element type the parameter is
// documented to use -- the matrix index type for a permutation, the matrix
// value type for the diagonal -- because nothing else checks it.
//
// dst is Go memory. Parameters the vendor documents as "host or device" may
// also be read into device memory, which this function cannot express; use
// DataArrayAt for that.
func DataArray[T ParamElement](handle Handle, data Data, param DataParam, dst []T) (int, error) {
	if len(dst) == 0 {
		return 0, nil
	}
	elem := unsafe.Sizeof(dst[0])
	written, err := dataGet(handle, data, param, unsafe.Pointer(&dst[0]), uintptr(len(dst))*elem)
	if err != nil {
		return 0, err
	}
	if written%elem != 0 {
		return 0, &ParamSizeError{Param: param.String(), Want: elem, Got: written}
	}
	return int(written / elem), nil
}

// SetDataArray writes an array-valued data parameter from src.
//
// src is Go memory and is read during the call. cuDSS documents that the
// arrays it accepts this way -- the user permutation, the user partition tree,
// the Schur indices -- are copied into an internal buffer, so src may be
// reused or collected once SetDataArray returns. Use SetDataArrayAt for a
// device address.
func SetDataArray[T ParamElement](handle Handle, data Data, param DataParam, src []T) error {
	if len(src) == 0 {
		return dataSet(handle, data, param, nil, 0)
	}
	return dataSet(handle, data, param, unsafe.Pointer(&src[0]), uintptr(len(src))*unsafe.Sizeof(src[0]))
}

// The Go bindings for cudssDataSet and cudssDataGet take unsafe.Pointer, which
// is right for Go memory and wrong for a device address: converting a uintptr
// to unsafe.Pointer to call them would be the exact pattern go vet's unsafeptr
// check exists to catch. So the two symbols are bound a second time with the
// value argument typed uintptr. The two bindings call the same code in the
// library; only the Go type of the argument differs.
var (
	addrOnce      sync.Once
	addrErr       error
	fnDataSetAddr func(Handle, Data, DataParam, uintptr, uint) Result
	fnDataGetAddr func(Handle, Data, DataParam, uintptr, uint, *uint) Result
)

// bindAddrFuncs loads the library and binds the uintptr-valued forms of
// cudssDataSet and cudssDataGet.
func bindAddrFuncs() error {
	if err := checkLib(); err != nil {
		return err
	}
	addrOnce.Do(func() {
		for _, b := range []struct {
			fn     any
			symbol string
		}{
			{&fnDataSetAddr, "cudssDataSet"},
			{&fnDataGetAddr, "cudssDataGet"},
		} {
			sym, err := purego.Dlsym(lib, b.symbol)
			if err != nil || sym == 0 {
				addrErr = &SymbolError{Symbol: b.symbol}
				return
			}
			purego.RegisterFunc(b.fn, sym)
		}
	})
	return addrErr
}

// DataArrayAt reads an array-valued data parameter into size bytes at addr.
//
// addr is an address the caller owns and this package cannot see into: a
// device allocation from cudaMalloc, or pinned host memory. It is not Go
// memory. Passing the address of a Go value here is a use-after-free waiting
// for the collector, because a uintptr keeps nothing alive.
//
// It reports how many bytes the library wrote.
func DataArrayAt(handle Handle, data Data, param DataParam, addr uintptr, size uintptr) (uintptr, error) {
	if err := bindAddrFuncs(); err != nil {
		return 0, err
	}
	var written uint
	if err := toError(fnDataGetAddr(handle, data, param, addr, uint(size), &written)); err != nil {
		return 0, err
	}
	return uintptr(written), nil
}

// SetDataArrayAt writes an array-valued data parameter from size bytes at
// addr. See DataArrayAt on what addr may be.
func SetDataArrayAt(handle Handle, data Data, param DataParam, addr uintptr, size uintptr) error {
	if err := bindAddrFuncs(); err != nil {
		return err
	}
	return toError(fnDataSetAddr(handle, data, param, addr, uint(size)))
}

