// SetDeviceIndices sets the device indices for multi-GPU execution, one per configured device.
//
// The slice fixes the byte count, so the call cannot write past it. The
// elements are int32 (int). cuDSS reads them during the call.
func (c Config) SetDeviceIndices(v []int32) error {
	if len(v) == 0 {
		return configSet(c, ConfigDeviceIndices, nil, 0)
	}
	return configSet(c, ConfigDeviceIndices, unsafe.Pointer(&v[0]), uintptr(len(v))*unsafe.Sizeof(v[0]))
}

// DeviceIndices reads the device indices for multi-GPU execution, one per configured device into dst and reports how many elements were written.
func (c Config) DeviceIndices(dst []int32) (int, error) {
	if len(dst) == 0 {
		return 0, nil
	}
	elem := unsafe.Sizeof(dst[0])
	n, err := configGet(c, ConfigDeviceIndices, unsafe.Pointer(&dst[0]), uintptr(len(dst))*elem)
	if err != nil {
		return 0, err
	}
	if n%elem != 0 {
		return 0, &ParamSizeError{Param: "CUDSS_CONFIG_DEVICE_INDICES", Want: elem, Got: n}
	}
	return int(n / elem), nil
}

